<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{{ $item->exists ? 'Edit Update' : 'New Update' }} | Peedam Admin</title><link rel="stylesheet" href="/astrol.css"><script src="/astrol.js" defer></script></head><body class="admin-page"><header class="admin-topbar"><a class="admin-brand" href="{{ route('admin.dashboard') }}"><span>☼</span><strong>Peedam Admin</strong></a><div class="admin-user"><span>{{ session('admin_user_name') }}</span><form method="POST" action="{{ route('admin.logout') }}">@csrf<button type="submit">Logout</button></form></div></header><div class="admin-shell">@include('admin._sidebar')<main class="admin-main"><div class="admin-list-heading"><div><a class="admin-back-link" href="{{ route('admin.news-events.index') }}">← All updates</a><h1>{{ $item->exists ? 'Edit update' : 'New update' }}</h1></div></div>@if ($errors->any())<div class="admin-error"><strong>Please correct the following:</strong><ul>@foreach ($errors->all() as $error)<li>{{ $error }}</li>@endforeach</ul></div>@endif<form class="admin-editor" method="POST" action="{{ $formAction }}" enctype="multipart/form-data" data-news-form>@csrf @if ($formMethod !== 'POST') @method($formMethod) @endif<div class="admin-editor-main"><label>Title<input name="title" value="{{ old('title', $item->title) }}" required></label><label>Slug<input name="slug" value="{{ old('slug', $item->slug) }}" placeholder="auto-generated-from-title"><small>Spaces are converted to hyphens automatically.</small></label><label>Event date<input type="date" name="event_date" value="{{ old('event_date', $item->event_date?->format('Y-m-d') ?: now()->format('Y-m-d')) }}" required></label><label>Content<div class="rich-editor"><div class="rich-toolbar"><button type="button" data-command="bold"><strong>B</strong></button><button type="button" data-command="italic"><em>I</em></button><button type="button" data-command="formatBlock" data-value="h2">H2</button><button type="button" data-command="insertUnorderedList">• List</button><button type="button" data-command="insertOrderedList">1. List</button><button type="button" data-command="createLink">Link</button><button type="button" data-upload-image>Upload Image</button><input type="file" accept="image/jpeg,image/png,image/gif,image/webp" data-image-input hidden></div><div class="rich-surface" contenteditable="true" data-rich-surface>@if (str_contains(old('content', $item->content), '<')){!! old('content', $item->content) !!}@else{!! nl2br(e(old('content', $item->content))) !!}@endif</div></div><textarea name="content" data-rich-content hidden></textarea><small>Format the update here and upload images directly from your computer.</small></label></div><aside class="admin-editor-side"><div class="admin-publish-note"><strong>Publishing</strong><span>Every saved update is published immediately with today’s date.</span></div><label>Cover image<input type="file" name="image" accept="image/jpeg,image/png,image/gif,image/webp" @if (!$item->exists) required @endif>@if ($item->image)<small>Current cover: {{ $item->image }}. Choose a new file only to replace it.</small><img class="admin-cover-preview" src="{{ $item->image_url }}" alt="Current cover image">@else<small>Required for new updates. Maximum 5 MB.</small>@endif</label><label>Publish date<input type="date" value="{{ now()->format('Y-m-d') }}" readonly></label><label class="admin-check"><input type="checkbox" checked disabled> Publish this update</label><button class="btn-primary" type="submit">Save update →</button></aside></form></main></div><script>const richSurface=document.querySelector('[data-rich-surface]');const richContent=document.querySelector('[data-rich-content]');document.querySelectorAll('[data-command]').forEach(button=>button.addEventListener('click',()=>{const command=button.dataset.command;if(command==='createLink'){const url=prompt('Enter link URL');if(url)document.execCommand(command,false,url);}else document.execCommand(command,false,button.dataset.value||null);richSurface.focus();}));const imageInput=document.querySelector('[data-image-input]');document.querySelector('[data-upload-image]')?.addEventListener('click',()=>imageInput.click());imageInput?.addEventListener('change',async()=>{if(!imageInput.files[0])return;const formData=new FormData();formData.append('image',imageInput.files[0]);const response=await fetch('{{ route('admin.blogs.upload-image') }}',{method:'POST',headers:{'X-CSRF-TOKEN':'{{ csrf_token() }}','Accept':'application/json'},body:formData});if(!response.ok){alert('Image upload failed. Please use an image smaller than 5 MB.');imageInput.value='';return;}const data=await response.json();richSurface.focus();document.execCommand('insertImage',false,data.url);imageInput.value='';});document.querySelector('[data-news-form]')?.addEventListener('submit',event=>{richContent.value=richSurface.innerHTML;if(!richSurface.innerText.trim()&&!richSurface.querySelector('img')){event.preventDefault();alert('Please add some content before saving.');richSurface.focus();}});</script></body></html>
